class DesktopReceive extends ConsumerStatefulWidget {
  const DesktopReceive({
    super.key,
    required this.walletId,
    this.clipboard = const ClipboardWrapper(),
  });

  final String walletId;
  final ClipboardInterface clipboard;

  @override
  ConsumerState<DesktopReceive> createState() => _DesktopReceiveState();
}

class _DesktopReceiveState extends ConsumerState<DesktopReceive> {
  late final CryptoCurrency coin;
  late final String walletId;
  late final ClipboardInterface clipboard;
  late final bool showMultiType;

  /// PIVX wallet with shield addresses (listed first: private by default).
  late final bool _supportsPivxShield;

  int _currentIndex = 0;

  final List<AddressType> _walletAddressTypes = [];
  final Map<AddressType, String> _addressMap = {};
  final Map<AddressType, StreamSubscription<Address?>> _addressSubMap = {};

  Future<void> generateNewAddress() async {
    final wallet = ref.read(pWallets).getWallet(walletId);
    if (wallet is! PivxWallet) return;
    final address = await showLoading<String?>(
      whileFuture: wallet.generateNewTransparentAddress(),
      context: context,
      message: l10n.receiveGeneratingAddress,
    );
    if (!mounted) return;
    if (address == null) {
      unawaited(
        showFloatingFlushBar(
          type: FlushBarType.info,
          message: pivxAddressGapMessage,
          context: context,
        ),
      );
      return;
    }
    setState(() => _addressMap[_walletAddressTypes[_currentIndex]] = address);
  }

  Future<void> generateNewPivxShieldAddress() async {
    final wallet = ref.read(pWallets).getWallet(walletId) as PivxWallet;
    final address = await showLoading<String>(
      whileFuture: wallet.generateNewShieldAddress(),
      context: context,
      message: l10n.receiveGeneratingAddress,
    );
    if (mounted && address != null) {
      setState(() => _addressMap[AddressType.pivxShield] = address);
    }
  }

  String _addressTypeLabel(AddressType type) =>
      _supportsPivxShield && type == AddressType.p2pkh
      ? l10n.receiveTransparentAddress
      : l10n.receiveTypeAddress(type.readableName);

  StreamSubscription<Address?> _sub(AddressType type) {
    return ref
        .read(mainDBProvider)
        .isar
        .addresses
        .where()
        .walletIdEqualTo(walletId)
        .filter()
        .typeEqualTo(type)
        .and()
        .subTypeEqualTo(AddressSubType.receiving)
        .sortByDerivationIndexDesc()
        .findFirst()
        .asStream()
        .listen((event) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) {
              setState(() {
                _addressMap[type] =
                    event?.value ??
                    _addressMap[type] ??
                    l10n.receiveNoAddressYet;
              });
            }
          });
        });
  }

  @override
  void initState() {
    walletId = widget.walletId;
    coin = ref.read(pWalletInfo(walletId)).coin;
    clipboard = widget.clipboard;
    final wallet = ref.read(pWallets).getWallet(walletId);
    _supportsPivxShield = wallet is PivxWallet && wallet.supportsShield;
    if (wallet is ViewOnlyOptionInterface && wallet.isViewOnly) {
      showMultiType = false;
    } else {
      showMultiType =
          _supportsPivxShield ||
          (wallet is Bip39HDWallet && wallet.supportedAddressTypes.length > 1);
    }

    _walletAddressTypes.add(wallet.info.mainAddressType);

    if (showMultiType) {
      if (_supportsPivxShield) {
        _walletAddressTypes.insert(0, AddressType.pivxShield);
      } else {
        _walletAddressTypes.addAll(
          (wallet as Bip39HDWallet).supportedAddressTypes.where(
            (e) => e != wallet.info.mainAddressType,
          ),
        );
      }
    }

    if (_supportsPivxShield) {
      _addressMap[wallet.info.mainAddressType] = ref.read(
        pWalletReceivingAddress(walletId),
      );
      _addressMap[AddressType.pivxShield] = l10n.receiveLoadingShield;
      (wallet as PivxWallet).getCurrentShieldAddress().then((a) {
        if (mounted && a != null) {
          setState(() => _addressMap[AddressType.pivxShield] = a);
        }
      });
    } else {
      _addressMap[_walletAddressTypes[_currentIndex]] = ref.read(
        pWalletReceivingAddress(walletId),
      );
    }

    if (showMultiType) {
      for (final type in _walletAddressTypes) {
        _addressSubMap[type] = _sub(type);
      }
    }

    super.initState();
  }

  @override
  void dispose() {
    for (final subscription in _addressSubMap.values) {
      subscription.cancel();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final String address;
    if (showMultiType) {
      address = _addressMap[_walletAddressTypes[_currentIndex]]!;
    } else {
      address = ref.watch(pWalletReceivingAddress(walletId));
    }

    final wallet = ref.watch(
      pWallets.select((value) => value.getWallet(walletId)),
    );

    final bool canGen;
    if (wallet is ViewOnlyOptionInterface &&
        wallet.isViewOnly &&
        wallet.viewOnlyType == ViewOnlyWalletType.addressOnly) {
      canGen = false;
    } else {
      canGen = wallet is MultiAddressInterface || _supportsPivxShield;
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const SizedBox(height: 4),
        const SizedBox(height: 20),
        ConditionalParent(
          condition: showMultiType,
          builder: (child) => Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              DropdownButtonHideUnderline(
                child: DropdownButton2<int>(
                  valueListenable: ValueNotifier(_currentIndex),
                  items: [
                    for (int i = 0; i < _walletAddressTypes.length; i++)
                      DropdownItem(
                        value: i,
                        child: Text(
                          _addressTypeLabel(_walletAddressTypes[i]),
                          style: STextStyles.w500_14(context),
                        ),
                      ),
                  ],
                  onChanged: (value) {
                    if (value != null && value != _currentIndex) {
                      setState(() {
                        _currentIndex = value;
                      });
                    }
                  },
                  isExpanded: true,
                  iconStyleData: IconStyleData(
                    icon: Padding(
                      padding: const EdgeInsets.only(right: 10),
                      child: SvgPicture.asset(
                        Assets.svg.chevronDown,
                        width: 12,
                        height: 6,
                        color: Theme.of(context)
                            .extension<StackColors>()!
                            .textFieldActiveSearchIconRight,
                      ),
                    ),
                  ),
                  buttonStyleData: ButtonStyleData(
                    decoration: BoxDecoration(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textFieldDefaultBG,
                      borderRadius: BorderRadius.circular(
                        Constants.size.circularBorderRadius,
                      ),
                    ),
                  ),
                  dropdownStyleData: DropdownStyleData(
                    offset: const Offset(0, -10),
                    elevation: 0,
                    decoration: BoxDecoration(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textFieldDefaultBG,
                      borderRadius: BorderRadius.circular(
                        Constants.size.circularBorderRadius,
                      ),
                    ),
                  ),
                  menuItemStyleData: const MenuItemStyleData(
                    padding: EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              child,
            ],
          ),
          child: MouseRegion(
            cursor: SystemMouseCursors.click,
            child: GestureDetector(
              onTap: () {
                clipboard.setData(ClipboardData(text: address));
                showFloatingFlushBar(
                  type: FlushBarType.info,
                  message: l10n.commonCopiedToClipboard,
                  iconAsset: Assets.svg.copy,
                  context: context,
                );
              },
              child: Container(
                decoration: BoxDecoration(
                  border: Border.all(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .backgroundAppBar,
                    width: 1,
                  ),
                  borderRadius: BorderRadius.circular(
                    Constants.size.circularBorderRadius,
                  ),
                ),
                child: RoundedWhiteContainer(
                  child: Column(
                    children: [
                      Row(
                        children: [
                          Text(
                            _supportsPivxShield &&
                                    _walletAddressTypes[_currentIndex] ==
                                        AddressType.pivxShield
                                ? l10n.receiveYourShieldAddress(coin.ticker)
                                : l10n.receiveYourAddress(coin.ticker),
                            style: STextStyles.itemSubtitle(context),
                          ),
                          const Spacer(),
                          Row(
                            children: [
                              SvgPicture.asset(
                                Assets.svg.copy,
                                width: 15,
                                height: 15,
                                color: Theme.of(context)
                                    .extension<StackColors>()!
                                    .infoItemIcons,
                              ),
                              const SizedBox(width: 4),
                              Text(
                                l10n.commonCopy,
                                style: STextStyles.link2(context),
                              ),
                            ],
                          ),
                        ],
                      ),
                      const SizedBox(height: 8),
                      Row(
                        children: [
                          Expanded(
                            child: Text(
                              address,
                              style:
                                  STextStyles.desktopTextExtraExtraSmall(
                                    context,
                                  ).copyWith(
                                    color: Theme.of(context)
                                        .extension<StackColors>()!
                                        .textDark,
                                  ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),

        if (canGen) const SizedBox(height: 20),

        if (canGen)
          SecondaryButton(
            buttonHeight: ButtonHeight.l,
            onPressed:
                _supportsPivxShield &&
                    _walletAddressTypes[_currentIndex] == AddressType.pivxShield
                ? generateNewPivxShieldAddress
                : generateNewAddress,
            label: l10n.receiveGenerateNew,
          ),
        const SizedBox(height: 20),
        Center(
          child: QR(
            data: AddressUtils.buildUriString(coin.uriScheme, address, {}),
            size: 200,
          ),
        ),
        const SizedBox(height: 32),

        // TODO: create transparent button class to account for hover
        // Conditional logic for 'Submit' button or QR code
        GestureDetector(
          onTap: () async {
            if (Util.isDesktop) {
              await showDialog<void>(
                context: context,
                builder: (context) => DesktopDialog(
                  maxHeight: double.infinity,
                  maxWidth: 580,
                  child: Column(
                    children: [
                      Row(
                        children: [
                          const AppBarBackButton(size: 40, iconSize: 24),
                          Text(
                            l10n.receiveGenerateQr,
                            style: STextStyles.desktopH3(context),
                          ),
                        ],
                      ),
                      IntrinsicHeight(
                        child: Navigator(
                          onGenerateRoute: RouteGenerator.generateRoute,
                          onGenerateInitialRoutes: (_, __) => [
                            RouteGenerator.generateRoute(
                              RouteSettings(
                                name: GenerateUriQrCodeView.routeName,
                                arguments: Tuple2(coin, address),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            } else {
              unawaited(
                Navigator.of(context).push(
                  RouteGenerator.getRoute(
                    shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
                    builder: (_) => GenerateUriQrCodeView(
                      coin: coin,
                      receivingAddress: address,
                    ),
                    settings: const RouteSettings(
                      name: GenerateUriQrCodeView.routeName,
                    ),
                  ),
                ),
              );
            }
          },
          child: Container(
            color: Colors.transparent,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                SvgPicture.asset(
                  Assets.svg.qrcode,
                  width: 14,
                  height: 16,
                  color: Theme.of(context)
                      .extension<StackColors>()!
                      .accentColorBlue,
                ),
                const SizedBox(width: 8),
                Text(
                  l10n.receiveCreateNewQr,
                  style: STextStyles.desktopTextExtraSmall(context).copyWith(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .accentColorBlue,
                  ),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }
}
